import React, { useRef } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { Download, Wifi, ShieldCheck } from 'lucide-react';
import { WiFiSettings, CardTheme } from '../types';

interface QRCodeDisplayProps {
  settings: WiFiSettings;
  qrValue: string;
  theme: CardTheme;
}

const QRCodeDisplay: React.FC<QRCodeDisplayProps> = ({ settings, qrValue, theme }) => {
  const cardRef = useRef<HTMLDivElement>(null);

  const downloadQR = () => {
    const svg = document.querySelector('#wifi-qr-svg') as SVGGraphicsElement;
    if (!svg) return;

    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = new Image();

    img.onload = () => {
      canvas.width = 1024;
      canvas.height = 1024;
      ctx?.drawImage(img, 0, 0, 1024, 1024);
      const pngFile = canvas.toDataURL('image/png');
      const downloadLink = document.createElement('a');
      downloadLink.download = `wifi-qr-${settings.ssid || 'network'}.png`;
      downloadLink.href = pngFile;
      downloadLink.click();
    };

    img.src = 'data:image/svg+xml;base64,' + btoa(svgData);
  };

  const hasContent = settings.ssid.trim().length > 0;

  return (
    <div className="flex flex-col items-center">
      {/* Printable Card Container */}
      <div 
        ref={cardRef}
        className={`w-full max-w-sm rounded-3xl p-8 shadow-xl transition-colors duration-500 relative overflow-hidden ${theme.bgClass} ${theme.textClass}`}
      >
        {/* Background Sparkles Decor */}
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/5 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute bottom-0 left-0 -ml-16 -mb-16 w-64 h-64 bg-white/5 rounded-full blur-3xl pointer-events-none" />

        <div className="relative z-10 flex flex-col items-center text-center space-y-6">
          <div className={`p-3 rounded-full ${theme.accentClass} inline-block`}>
            <Wifi className="w-8 h-8" />
          </div>

          <div className="space-y-1">
            <h3 className="text-2xl font-bold tracking-tight">Guest Wi-Fi</h3>
            <p className="text-sm opacity-80 uppercase tracking-widest font-medium">Scan to Connect</p>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-inner border border-white/20">
            {hasContent ? (
              <QRCodeSVG
                id="wifi-qr-svg"
                value={qrValue}
                size={220}
                level="M"
                includeMargin={false}
              />
            ) : (
              <div className="w-[220px] h-[220px] bg-gray-50 rounded-lg flex flex-col items-center justify-center text-gray-400 space-y-2">
                <Wifi className="w-10 h-10 opacity-20" />
                <span className="text-xs">Enter SSID to generate</span>
              </div>
            )}
          </div>

          <div className="w-full space-y-3 pt-2">
            <div className="flex flex-col items-center space-y-1">
              <span className="text-xs opacity-60 font-semibold uppercase tracking-wider">Network</span>
              <p className="text-lg font-semibold truncate max-w-full">
                {settings.ssid || '---'}
              </p>
            </div>
            {settings.encryption !== 'nopass' && (
              <div className="flex flex-col items-center space-y-1">
                <span className="text-xs opacity-60 font-semibold uppercase tracking-wider">Password</span>
                <p className="text-sm font-mono bg-black/10 px-3 py-1 rounded-md">
                  {settings.password || '••••••••'}
                </p>
              </div>
            )}
          </div>

          <div className="flex items-center justify-center space-x-2 pt-4 border-t border-white/10 w-full opacity-60">
            <ShieldCheck className="w-4 h-4" />
            <span className="text-xs font-medium">Secured with {settings.encryption}</span>
          </div>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="mt-8 flex flex-col sm:flex-row gap-4 w-full max-w-sm no-print">
        <button
          onClick={downloadQR}
          disabled={!hasContent}
          className="flex-1 inline-flex justify-center items-center px-6 py-3 border border-gray-300 shadow-sm text-sm font-medium rounded-xl text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <Download className="w-4 h-4 mr-2" />
          Save Image
        </button>
      </div>

      {/* Specific Print Instructions (Visible only when printing) */}
      <div className="print-only text-center mt-8 text-gray-400 text-xs">
        <p>Created with Wi-Fi Spark</p>
      </div>
    </div>
  );
};

export default QRCodeDisplay;

{
  "name": "Wi-Fi Spark",
  "description": "A professional and elegant Wi-Fi QR code generator that helps guests connect to your network instantly without typing long passwords.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useRef, useState, useEffect } from 'react';
import { Camera, X, RefreshCw, Zap, AlertCircle } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { WiFiSettings } from '../types';

interface RouterScannerProps {
  onScanSuccess: (settings: Partial<WiFiSettings>) => void;
  onClose: () => void;
}

const RouterScanner: React.FC<RouterScannerProps> = ({ onScanSuccess, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCapturing, setIsCapturing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    async function setupCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
        setIsCapturing(true);
      } catch (err) {
        setError('Could not access camera. Please ensure you have granted permission.');
        console.error(err);
      }
    }
    setupCamera();

    return () => {
      if (videoRef.current?.srcObject) {
        const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
        tracks.forEach(track => track.stop());
      }
    };
  }, []);

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsAnalyzing(true);
    setError(null);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx?.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
            { text: "Extract the Wi-Fi SSID and Password from this router sticker. Return ONLY a JSON object with keys 'ssid' and 'password'. If you can't find them, return empty strings." }
          ]
        },
        config: {
          responseMimeType: "application/json"
        }
      });

      const result = JSON.parse(response.text || '{}');
      if (result.ssid) {
        onScanSuccess({
          ssid: result.ssid,
          password: result.password || '',
          encryption: 'WPA' // Default to WPA as it's most common on labels
        });
        onClose();
      } else {
        setError("Could not find Wi-Fi details. Please try a clearer photo.");
      }
    } catch (err) {
      setError("Failed to analyze image. Please try again.");
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-lg overflow-hidden relative shadow-2xl">
        <div className="p-4 border-b flex justify-between items-center">
          <div className="flex items-center space-x-2">
            <Zap className="w-5 h-5 text-indigo-600 fill-indigo-600" />
            <h2 className="font-bold text-gray-900">AI Router Scanner</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <div className="relative aspect-square bg-black overflow-hidden">
          {isCapturing ? (
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center">
              <RefreshCw className="w-8 h-8 text-white animate-spin" />
            </div>
          )}

          {/* Viewfinder overlay */}
          <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
            <div className="w-full h-full border-2 border-dashed border-white/50 rounded-lg flex items-center justify-center">
              <div className="text-white/70 text-xs font-medium bg-black/40 px-3 py-1 rounded-full uppercase tracking-widest">
                Center Router Label
              </div>
            </div>
          </div>

          {isAnalyzing && (
            <div className="absolute inset-0 bg-indigo-600/20 backdrop-blur-[2px] flex flex-col items-center justify-center space-y-4">
              <div className="relative">
                <div className="w-16 h-16 border-4 border-white/30 border-t-white rounded-full animate-spin" />
                <Zap className="absolute inset-0 m-auto w-6 h-6 text-white animate-pulse" />
              </div>
              <p className="text-white font-bold text-lg drop-shadow-md">AI Reading Sticker...</p>
            </div>
          )}
        </div>

        <div className="p-6 space-y-4">
          {error && (
            <div className="flex items-center space-x-2 text-rose-600 bg-rose-50 p-3 rounded-xl border border-rose-100">
              <AlertCircle className="w-5 h-5 shrink-0" />
              <p className="text-sm font-medium">{error}</p>
            </div>
          )}

          <button
            onClick={captureAndAnalyze}
            disabled={isAnalyzing || !isCapturing}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-gray-300 text-white rounded-xl font-bold flex items-center justify-center space-x-2 transition-all shadow-lg active:scale-[0.98]"
          >
            <Camera className="w-5 h-5" />
            <span>{isAnalyzing ? 'Processing...' : 'Capture Label'}</span>
          </button>

          <p className="text-xs text-center text-gray-500 leading-relaxed px-4">
            Point your camera at the Wi-Fi info sticker on your router. Our AI will automatically detect the name and password.
          </p>
        </div>
      </div>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default RouterScanner;

