import { WiFiSettings } from '../types';

/**
 * Escapes special characters for WiFi QR code strings
 */
const escapeValue = (value: string): string => {
  return value.replace(/([\\;,:"])/g, '\\$1');
};

/**
 * Generates the standard WIFI QR code string
 */
export const generateWiFiQRString = (settings: WiFiSettings): string => {
  const ssid = escapeValue(settings.ssid);
  const password = settings.encryption === 'nopass' ? '' : escapeValue(settings.password);
  const hidden = settings.hidden ? 'true' : '';

  return `WIFI:S:${ssid};T:${settings.encryption};P:${password};H:${hidden};;`;
};

/**
 * Generates an Apple .mobileconfig file content
 * This allows "scan-less" connection on iOS/macOS
 */
export const generateMobileConfig = (settings: WiFiSettings): string => {
  const uuid1 = crypto.randomUUID();
  const uuid2 = crypto.randomUUID();

  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>PayloadContent</key>
	<array>
		<dict>
			<key>AutoJoin</key>
			<true/>
			<key>EncryptionType</key>
			<string>${settings.encryption === 'nopass' ? 'None' : 'Any'}</string>
			<key>HIDDEN_NETWORK</key>
			<${settings.hidden ? 'true' : 'false'}/>
			<key>Password</key>
			<string>${settings.password}</string>
			<key>PayloadDescription</key>
			<string>Configures Wi-Fi settings</string>
			<key>PayloadDisplayName</key>
			<string>Wi-Fi (${settings.ssid})</string>
			<key>PayloadIdentifier</key>
			<string>com.wifispark.config.${uuid1}</string>
			<key>PayloadType</key>
			<string>com.apple.wifi.managed</string>
			<key>PayloadUUID</key>
			<string>${uuid1}</string>
			<key>PayloadVersion</key>
			<integer>1</integer>
			<key>SSID_STR</key>
			<string>${settings.ssid}</string>
		</dict>
	</array>
	<key>PayloadDisplayName</key>
	<string>Wi-Fi Spark: ${settings.ssid}</string>
	<key>PayloadIdentifier</key>
	<string>com.wifispark.profile.${uuid2}</string>
	<key>PayloadRemovalDisallowed</key>
	<false/>
	<key>PayloadType</key>
	<string>Configuration</string>
	<key>PayloadUUID</key>
	<string>${uuid2}</string>
	<key>PayloadVersion</key>
	<integer>1</integer>
</dict>
</plist>`;
};

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Search, MapPin, SignalHigh, Loader2, ArrowRight } from 'lucide-react';

interface NearbyScannerProps {
  onSelect: (ssid: string) => void;
}

const NearbyScanner: React.FC<NearbyScannerProps> = ({ onSelect }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [results, setResults] = useState<{ ssid: string, venue: string }[]>([]);
  const [error, setError] = useState<string | null>(null);

  const scanNearby = async () => {
    setIsScanning(true);
    setError(null);
    setResults([]);

    try {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject);
      });

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: "Find the names of 5 nearby businesses or public places and predict their common Wi-Fi SSID names. Return ONLY a JSON array of objects with keys 'ssid' and 'venue'.",
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: {
                latitude: position.coords.latitude,
                longitude: position.coords.longitude
              }
            }
          }
        },
      });

      // The response might not be clean JSON if grounding adds text, so we attempt to parse
      const text = response.text || "[]";
      const jsonStart = text.indexOf('[');
      const jsonEnd = text.lastIndexOf(']') + 1;
      const jsonStr = text.substring(jsonStart, jsonEnd);

      const foundNetworks = JSON.parse(jsonStr || "[]");
      setResults(foundNetworks);
    } catch (err) {
      console.error(err);
      setError("Unable to find nearby networks. Please ensure location services are enabled.");
    } finally {
      setIsScanning(false);
    }
  };

  return (
    <div className="space-y-4">
      <button
        onClick={scanNearby}
        disabled={isScanning}
        className="w-full flex items-center justify-center space-x-2 py-3 px-4 bg-indigo-50 text-indigo-700 rounded-xl hover:bg-indigo-100 transition-colors border border-indigo-100 font-medium"
      >
        {isScanning ? (
          <Loader2 className="w-4 h-4 animate-spin" />
        ) : (
          <Search className="w-4 h-4" />
        )}
        <span>{isScanning ? 'Scanning Nearby...' : 'Scan for Nearby Networks'}</span>
      </button>

      {error && <p className="text-xs text-rose-500 text-center">{error}</p>}

      <div className="space-y-2">
        {results.map((net, i) => (
          <button
            key={i}
            onClick={() => onSelect(net.ssid)}
            className="w-full flex items-center justify-between p-3 bg-white border border-gray-100 rounded-xl hover:border-indigo-300 hover:shadow-sm transition-all text-left group"
          >
            <div className="flex items-center space-x-3">
              <div className="bg-gray-50 p-2 rounded-lg group-hover:bg-indigo-50 transition-colors">
                <MapPin className="w-4 h-4 text-gray-400 group-hover:text-indigo-500" />
              </div>
              <div>
                <p className="text-sm font-bold text-gray-900">{net.ssid}</p>
                <p className="text-[10px] text-gray-500 uppercase tracking-tight font-medium">{net.venue}</p>
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <SignalHigh className="w-4 h-4 text-emerald-500" />
              <ArrowRight className="w-4 h-4 text-gray-300 group-hover:text-indigo-500 transition-colors" />
            </div>
          </button>
        ))}
      </div>
    </div>
  );
};

