                className="w-full bg-[#2d2d2d] border-b-2 border-transparent focus:border-[#60cdff] outline-none py-1.5 px-3 text-sm rounded-t-md transition-all placeholder:text-gray-500 group-hover:bg-[#353535]"
              />
              <Search className="absolute right-3 top-2.5 w-4 h-4 text-gray-500 pointer-events-none" />
            </div>
          </div>

          {/* Network List */}
          <div className="flex-grow overflow-y-auto custom-scrollbar bg-[#1c1c1c]">
            {isScanning && results.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 space-y-4">
                <div className="relative">
                  <Wifi className="w-10 h-10 text-gray-700" />
