 */
interface NetworkResult {
  ssid: string;
  secured: boolean;
  proximity: string;
  type?: 'primary' | 'normal';
  connected?: boolean;
}

interface NearbyScannerProps {
  currentSSID?: string;
  onSelect: (ssid: string) => void;
}

const NearbyScanner: React.FC<NearbyScannerProps> = ({ currentSSID, onSelect }) => {
  const [isScanning, setIsScanning] = useState(false);
  // Using the defined interface to ensure consistent property access
  const [results, setResults] = useState<NetworkResult[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedSSID, setSelectedSSID] = useState<string | null>(null);
  const [isWifiOn, setIsWifiOn] = useState(true);

  const scanNearby = async () => {
    if (!isWifiOn) return;
    setIsScanning(true);
    setError(null);
    setResults([]);
    setSearchQuery('');
    setSelectedSSID(null);

    try {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 10000 });
      });

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `You are simulating a Wi-Fi hardware scanner at ${position.coords.latitude}, ${position.coords.longitude}. Find exactly 5 Wi-Fi SSIDs within an extremely close 1-meter radius (simulating near-field detection). Priority: 1. The user's specific router. 2. Personal hotspots in immediate reach. Return JSON: array of { ssid, secured, proximity }.`,
      });

      const text = response.text || "[]";
      const jsonStart = text.indexOf('[');
      const jsonEnd = text.lastIndexOf(']') + 1;
      const jsonStr = text.substring(jsonStart, jsonEnd);

      // Explicitly typing the parsed results to allow adding the 'type' property
      let foundNetworks: NetworkResult[] = JSON.parse(jsonStr || "[]");

      // MANDATORY: If the user has entered an SSID, we "find" it compulsorily
      if (currentSSID && currentSSID.trim().length > 0) {
        const alreadyExists = foundNetworks.some((n: NetworkResult) => n.ssid.toLowerCase() === currentSSID.toLowerCase());
        if (!alreadyExists) {
          // Fix: Explicitly cast the object to NetworkResult to ensure 'type' is correctly typed as 'primary' | 'normal'
          const primaryNetwork: NetworkResult = { 
            ssid: currentSSID, 
            secured: true, 
            proximity: '0.1m', 
            type: 'primary' 
          };
          foundNetworks = [primaryNetwork, ...foundNetworks];
        } else {
          // If it was already predicted, promote it
          foundNetworks = foundNetworks.map((n: NetworkResult) => 
            n.ssid.toLowerCase() === currentSSID.toLowerCase() 
            ? { ...n, type: 'primary' as const, proximity: '0.1m' } 
            : n
          ).sort((a: NetworkResult, b: NetworkResult) => (a.type === 'primary' ? -1 : 1));
        }
      }

      setResults(foundNetworks);
    } catch (err) {
      console.error(err);
      setError("AI Scan unavailable. Showing hyper-local simulation.");
      const mock: NetworkResult[] = [
        { ssid: "Local_Network_5G", secured: true, proximity: "0.4m" },
        { ssid: "Smartphone_Hotspot", secured: true, proximity: "0.9m" }
